using System;
using System.Linq;
using DesktopCritters.Core;
namespace DesktopCritters;
public static class EggSprayTests {
 private static World Empty(){var w=new World(1440,900,88);w.Bugs.Clear();w.Foods.Clear();w.Eggs.Clear();w.Serial=1000;w.InvasionTimer=10000;w.AutoFoodTimer=-10000;w.RoachBirth=w.AntBirth=10000;return w;}
 public static void Run(Action<bool,string> check){var n=Empty();n.MarkShelter(new V(600,400));check(n.Shelters.Count==1,"folder shelter can be marked without filesystem access");n.MarkShelter(new V(600,400));check(n.Shelters.Count==0,"repeat click removes shelter");for(int i=0;i<9;i++)n.MarkShelter(new V(150+i*100,400));check(n.Shelters.Count==6,"folder hiding regions bounded");
  var w=Empty();w.MarkShelter(new V(600,400));var mother=new Bug{Id=1,Species=Species.Roach,P=new V(535,400),Breeder=true};w.Bugs.Add(mother);w.RoachBirth=0;w.Life(.05);var e=w.Eggs[0];check(e.ParentId==1&&e.LayAge==0&&mother.LayTime==2.8,"natural birth attaches egg extrusion to a stopped parent");var tail=e.ShownPoint;check(tail!=e.P&&e.Emission==0,"egg begins inside abdomen");var at=mother.P;w.Update(.05);check(mother.P==at,"laying mother stays still");check(!w.BeginFlight(mother),"laying mother cannot fly");w.Life(1.35);check(e.ShownPoint.Distance(tail)>1&&e.ShownPoint.Distance(e.P)>1&&e.Age==0,"egg slides out before incubation starts");w.Life(1.5);check(e.Emission==1&&w.EggOccluded(e),"egg moves behind marked folder mask");w.Tool=Tool.Observe;w.Watched=e.Id;check(!w.EggOccluded(e),"observing reveals hidden egg");w.Tool=Tool.Food;w.Life(29);check(w.Bugs.Any(b=>!b.Adult&&!w.Shelters[0].Contains(b.P)),"hidden eggs hatch outside icon edge");var restored=Empty();restored.Restore(w.SaveJson());check(restored.Shelters.Count==1&&restored.Bugs.Count==w.Bugs.Count,"folder shelter persists with colony");
  var s=Empty();s.Interactive=true;var flyer=new Bug{Id=1,Species=Species.Roach,P=new V(500,400)};s.Bugs.AddRange(new[]{flyer,new Bug{Id=2,Species=Species.Ant,P=new V(530,400)},new Bug{Id=3,Species=Species.Ant,P=new V(1100,400)}});s.BeginFlight(flyer);s.Eggs.Add(new Egg{Id=99,Species=Species.Roach,P=new V(500,400),HatchTime=28});s.Tool=Tool.Spray;s.Press(new V(500,400));check(s.Bugs.Count==1&&s.Bugs[0].Id==3&&s.Corpses.Count==2,"spray kills nearby flying and ground insects only");check(s.Splats.Count==1&&!s.Splats[0].Crushed&&s.Eggs.Count==1,"spray leaves corpse and liquid while eggs survive");check(s.Corpses.All(b=>b.Flight==null)&&s.Today.Events.Any(x=>x.Contains("杀虫剂")),"spray stops flight and records cause of death");int clouds=s.Sprays.Count;s.Press(new V(500,400));check(s.Sprays.Count==clouds,"spray emission rate limited");s.Bugs.Add(new Bug{Id=4,Species=Species.Ant,P=new V(500,400)});s.Update(.05);check(!s.Bugs.Any(b=>b.Id==4),"insects entering active mist die");s.Paused=true;double age=s.Sprays[0].Age;s.Update(.05);s.SprayCooldown=0;s.Spray(new V(1100,400));check(s.Bugs.Count==1&&s.Sprays[0].Age==age,"pause freezes mist and prevents kills");s.Paused=false;s.SweepAt(new V(500,400));check(s.Corpses.Count==0&&s.Splats.Count==0,"broom cleans sprayed corpses and liquid");var reload=Empty();reload.Restore(s.SaveJson());check(reload.Sprays.Count==0,"lethal mist never replays after restart");for(int i=0;i<30;i++){s.SprayCooldown=0;s.Spray(new V(600,500));}check(s.Sprays.Count<=8,"spray cloud budget remains bounded");
 }
}
